display.text:
/**
 * GateRunner 执行确定性的 Spec 流程门禁。
 *
 * creation / ready / completion 只核对文件结构、模板哨兵和 Task 状态；
 * 需求质量和实现判断仍交给 AI 与用户，不在这里调用 LLM 或读取源码。
 */

import { FileStorage } from '../storage/FileStorage.js';
import { parseFrontmatter } from '../storage/FrontmatterCodec.js';
import { extractCodeRanges, inRanges } from '../storage/MarkdownParser.js';
import { LrnevError, ErrorCode } from '../shared/errors.js';
import { findLegacyTodoPlaceholders } from './LegacyTodoMigration.js';
import { SceneManager } from './SceneManager.js';
import { SpecManager } from './SpecManager.js';
import { TaskManager } from './TaskManager.js';
import { getHookManager } from './HookManager.js';
import type { GateCheck, GateCheckInput, GateResult, GateType, LocatedLine } from '../types/gate.js';
import type { SpecFrontmatter } from '../types/spec.js';
import type { Task } from '../types/task.js';

const REQUIRED_REQUIREMENTS_SECTIONS = [
  'L0 摘要',
  'L1 概览',
  'L2 详情',
  '范围',
  '详细需求',
  '验收标准',
];

export class GateRunner {
  constructor(
    private readonly fs: FileStorage,
    private readonly sceneManager: SceneManager,
    private readonly specManager: SpecManager,
    private readonly taskManager: TaskManager,
  ) {}

  async check(gate: GateType, input: GateCheckInput): Promise<GateResult> {
    switch (gate) {
      case 'creation':
        return this.checkCreation(input);
      case 'ready':
        return this.checkReady(input);
      case 'completion':
        return this.checkCompletion(input);
      default:
        throw new LrnevError(ErrorCode.INVALID_INPUT, `未知 gate 类型："${String(gate)}"`, {
          field: 'gate',
          hint: 'gate 只接受 creation / ready / completion。',
        });
    }
  }

  async checkCreation(input: GateCheckInput): Promise<GateResult> {
    return (await this.checkCreationDetails(input)).result;
  }

  async checkReady(input: GateCheckInput): Promise<GateResult> {
    const creation = await this.checkCreationDetails(input);
    const checks = [...creation.result.checks];

    if (creation.content !== undefined) {
      // ready gate 只检查结构契约；正文里的业务判断不在 lrnev 内裁决。
      const missingSections = findMissingSections(creation.content, REQUIRED_REQUIREMENTS_SECTIONS);
      checks.push({
        name: 'requirements_sections_present',
        passed: missingSections.length === 0,
        hard_fail: true,
        ...(missingSections.length > 0 && {
          message: `requirements.md 缺少必填章节：${missingSections.join(', ')}`,
          hint: '章节标题必须与模板完全一致（中文原文：L0 摘要 / L1 概览 / L2 详情 / 范围 / 详细需求 / 验收标准），不要翻译或改名——缺失或被改名都会判失败。',
        }),
      });

      const sentinels = findFillSentinels(creation.content);
      checks.push({
        name: 'requirements_no_fill_sentinels',
        passed: sentinels.length === 0,
        hard_fail: true,
        ...(sentinels.length > 0 && {
          message: `requirements.md 仍有未填哨兵：${sentinels
            .slice(0, 5)
            .map((item) => `L${item.line}`)
            .join(', ')}`,
          hint: '把 <!-- FILL: ... --> 替换为具体内容；旧 TODO 占位可先运行 lrnev doctor --migrate-todos',
        }),
      });

      const legacyTodos = findLegacyTodoPlaceholders(creation.content);
      checks.push({
        name: 'requirements_no_legacy_todo_placeholders',
        passed: legacyTodos.length === 0,
        hard_fail: true,
        ...(legacyTodos.length > 0 && {
          message: `requirements.md 仍有旧 TODO 模板占位：${legacyTodos
            .slice(0, 5)
            .map((item) => `L${item.line}`)
            .join(', ')}`,
          hint: '先运行 lrnev doctor --migrate-todos 把旧模板 TODO 占位迁移为 <!-- FILL: ... -->',
        }),
      });

      const unchecked = findUncheckedItems(creation.content);
      checks.push({
        name: 'requirements_acceptance_checked',
        passed: unchecked.length === 0,
        hard_fail: false,
        ...(unchecked.length > 0 && {
          message: `requirements.md 仍有未勾选清单项：${unchecked
            .slice(0, 5)
            .map((item) => `L${item.line}`)
            .join(', ')}`,
          hint: '确认验收清单已完成后，把 - [ ] 改为 - [x]',
        }),
      });
    }

    const result = buildResult('ready', checks);
    if (result.passed) {
      const hookResult = await getHookManager(this.fs.root).trigger('spec.gate_passed.ready', {
        scene: creation.sceneId,
        spec: creation.specId,
        gate: 'ready',
      });
      appendHookWarningCheck(result.checks, hookResult.warnings);
    }
    return result;
  }

  async checkCompletion(input: GateCheckInput): Promise<GateResult> {
    const creationDetails = await this.checkCreationDetails(input);
    const checks = [...creationDetails.result.checks];

    let tasks: Task[];
    try {
      tasks = await this.taskManager.list(input.scene, input.spec);
      checks.push({
        name: 'tasks_readable',
        passed: true,
        hard_fail: true,
      });
    } catch (err) {
      checks.push({
        name: 'tasks_readable',
        passed: false,
        hard_fail: true,
        message: `tasks.md 读取或解析失败：${err instanceof Error ? err.message : String(err)}`,
        hint: '检查 tasks.md 结构，必要时运行 lrnev doctor',
      });
      return buildResult('completion', checks);
    }

    checks.push({
      name: 'tasks_exist',
      passed: tasks.length > 0,
      hard_fail: true,
      ...(tasks.length === 0 && {
        message: 'Spec 内没有任何 Task',
        hint: '先调用 task_create 或补齐 tasks.md',
      }),
    });

    const incomplete = tasks.filter((task) => task.status !== 'completed');
    checks.push({
      name: 'all_tasks_completed',
      passed: tasks.length > 0 && incomplete.length === 0,
      hard_fail: true,
      ...(incomplete.length > 0 && {
        message: `仍有未完成 Task：${incomplete.map((task) => `${task.id}:${task.status}`).join(', ')}`,
        hint: '完成所有 Task 后再检查 completion gate',
      }),
    });

    // I-4: completion 硬拦 requirements/design 残留 FILL 哨兵。
    // FILL 是确定性结构事实（非语义判断），用精确的 findFillSentinels（已排除代码块/正文里的 FILL 词）。
    // 不查 tasks.md：其模板自带 FILL（task_create 只追加任务、不替换占位）。
    if (creationDetails.content !== undefined) {
      const reqFill = findFillSentinels(creationDetails.content);
      checks.push({
        name: 'requirements_no_fill',
        passed: reqFill.length === 0,
        hard_fail: true,
        ...(reqFill.length > 0 && {
          message: `requirements.md 仍有未填哨兵：${reqFill.slice(0, 5).map((s) => `L${s.line}`).join(', ')}`,
          hint: '把 <!-- FILL: ... --> 替换为具体内容后再检查 completion',
        }),
      });
    }

    const designPath = `.lrnev/scenes/${creationDetails.sceneId}/specs/${creationDetails.specId}/design.md`;
    const designExists = this.fs.exists(designPath);
    // design.md 缺失必须显式 fail：否则“删掉 design.md”就能绕过 FILL 硬拦（codex 复核发现的放行缺口）。
    checks.push({
      name: 'design_exists',
      passed: designExists,
      hard_fail: true,
      ...(!designExists && {
        message: `design.md 不存在：${designPath}`,
        hint: 'spec 骨架应含 design.md；请恢复文件或重新 spec_create，缺失时 completion 不能通过。',
      }),
    });
    if (designExists) {
      const designFill = findFillSentinels(await this.fs.read(designPath));
      checks.push({
        name: 'design_no_fill',
        passed: designFill.length === 0,
        hard_fail: true,
        ...(designFill.length > 0 && {
          message: `design.md 仍有未填哨兵：${designFill.slice(0, 5).map((s) => `L${s.line}`).join(', ')}`,
          hint: '把 design.md 的 <!-- FILL: ... --> 替换为具体内容后再检查 completion',
        }),
      });
    }

    const result = buildResult('completion', checks);
    if (result.passed) {
      const { sceneId, specId } = await this.resolveSpecPaths(input);
      const hookResult = await getHookManager(this.fs.root).trigger('spec.gate_passed.completion', {
        scene: sceneId,
        spec: specId,
        gate: 'completion',
      });
      appendHookWarningCheck(result.checks, hookResult.warnings);
    }
    return result;
  }

  private async checkCreationDetails(input: GateCheckInput): Promise<{
    result: GateResult;
    sceneId: string;
    specId: string;
    reqPath: string;
    content?: string;
  }> {
    const checks: GateCheck[] = [];
    const { sceneId, specId, reqPath } = await this.resolveSpecPaths(input);
    const exists = this.fs.exists(reqPath);

    checks.push({
      name: 'requirements_exists',
      passed: exists,
      hard_fail: true,
      ...(!exists && {
        message: `requirements.md 不存在：${reqPath}`,
        hint: '先调用 spec_create 创建 Spec 骨架',
      }),
    });

    let content: string | undefined;
    if (exists) {
      content = await this.fs.read(reqPath);
      const parsed = parseFrontmatter<Partial<SpecFrontmatter>>(content);
      const fm = parsed.frontmatter;
      checks.push(this.checkRequiredField('frontmatter_spec', fm.spec === specId, 'spec'));
      checks.push(this.checkRequiredField('frontmatter_scene', fm.scene === sceneId, 'scene'));
      checks.push(this.checkRequiredField('frontmatter_status', typeof fm.status === 'string', 'status'));
      checks.push(this.checkRequiredField('frontmatter_created', typeof fm.created === 'string', 'created'));
    }

    return {
      result: buildResult('creation', checks),
      sceneId,
      specId,
      reqPath,
      ...(content !== undefined && { content }),
    };
  }

  private async resolveSpecPaths(input: GateCheckInput): Promise<{
    sceneId: string;
    specId: string;
    reqPath: string;
  }> {
    const sceneId = await this.sceneManager.resolveId(input.scene);
    let specId: string;
    try {
      specId = await this.specManager.resolveId(sceneId, input.spec);
    } catch (err) {
      if (err instanceof LrnevError && err.code === ErrorCode.SPEC_NOT_FOUND && /^\d+-\d+-/.test(input.spec)) {
        specId = input.spec;
      } else {
        throw err;
      }
    }
    return {
      sceneId,
      specId,
      reqPath: `.lrnev/scenes/${sceneId}/specs/${specId}/requirements.md`,
    };
  }

  private checkRequiredField(name: string, passed: boolean, field: string): GateCheck {
    return {
      name,
      passed,
      hard_fail: true,
      ...(!passed && {
        message: `requirements.md frontmatter 缺少或不匹配字段：${field}`,
        hint: `修正 requirements.md 顶部 frontmatter 的 ${field} 字段`,
      }),
    };
  }
}

function buildResult(gate: GateType, checks: GateCheck[]): GateResult {
  return {
    gate,
    passed: checks.every((check) => check.passed || !check.hard_fail),
    checks,
  };
}

function appendHookWarningCheck(checks: GateCheck[], warnings: string[]): void {
  if (warnings.length === 0) return;
  checks.push({
    name: 'hook_warnings',
    passed: false,
    hard_fail: false,
    message: warnings.join('\n'),
    hint: 'Hook 以 warn 策略失败，主流程继续；请查看 .lrnev/state/hook-log.jsonl 排查。',
  });
}

export function findFillSentinels(content: string): LocatedLine[] {
  const matches: LocatedLine[] = [];
  const codeRanges = extractCodeRanges(content);
  for (const line of iterateLines(content)) {
    const regex = /<!--\s*FILL(?::.*?)?\s*-->/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(line.text)) !== null) {
      const start = line.start + match.index;
      const end = start + match[0]!.length;
      if (inRanges(codeRanges, start, end)) continue;
      matches.push({ line: line.number, text: line.text.trim() });
      break;
    }
  }
  return matches;
}

export function findMissingSections(content: string, requiredTitles: string[]): string[] {
  const existing = collectMarkdownHeadings(content);
  return requiredTitles.filter((title) => !existing.has(title));
}

function collectMarkdownHeadings(content: string): Set<string> {
  const headings = new Set<string>();
  const codeRanges = extractCodeRanges(content);
  for (const line of iterateLines(content)) {
    if (inRanges(codeRanges, line.start, line.end)) continue;
    const match = /^(#{2,6})\s+(.+?)\s*$/.exec(line.text);
    if (match) headings.add(match[2]!.trim());
  }
  return headings;
}

export function findUncheckedItems(content: string): LocatedLine[] {
  const matches: LocatedLine[] = [];
  const codeRanges = extractCodeRanges(content);
  for (const line of iterateLines(content)) {
    const match = /^\s*[-*]\s+\[\s\]\s+/.exec(line.text);
    if (!match) continue;
    if (inRanges(codeRanges, line.start + match.index, line.start + match.index + match[0].length)) continue;
    matches.push({ line: line.number, text: line.text.trim() });
  }
  return matches;
}

function iterateLines(content: string): Array<{ number: number; text: string; start: number; end: number }> {
  const lines = content.split(/\r?\n/);
  const eols = content.match(/\r?\n/g) ?? [];
  const result: Array<{ number: number; text: string; start: number; end: number }> = [];
  let offset = 0;
  for (let i = 0; i < lines.length; i++) {
    const text = lines[i]!;
    const start = offset;
    const end = start + text.length;
    result.push({ number: i + 1, text, start, end });
    offset = end + (eols[i]?.length ?? 0);
  }
  return result;
}

/**
 * SpecManager —— Spec 管理（增删查 + Scene 内序号 + 版本号）
 *
 * 职责（详见 design.md 第 6.2 节）：
 *   1. list(scene)       —— 列出该 Scene 下所有 Spec
 *   2. get(scene, spec)  —— 读单个 Spec（路径 + frontmatter + 三文档存在性）
 *   3. create(...)       —— Scene 内序号 + 三文档（requirements/design/tasks）+ ai_followup
 *   4. resolveId(...)    —— 用户输入归一化
 *
 * 命名约定：
 *   "{NN:02d}-{VV:02d}-{kebab-name}"
 *   NN：Scene 内递增序号（不重用）
 *   VV：版本号，默认 00（重写时升 01/02...）
 *
 * 例：01-00-user-registration、02-00-user-login、01-01-user-registration(重写版)
 */

import { parseFrontmatter, serializeFrontmatter } from '../storage/FrontmatterCodec.js';
import { FileStorage } from '../storage/FileStorage.js';
import { LrnevError, ErrorCode } from '../shared/errors.js';
import { loadConfig } from '../shared/config.js';
import { renderTemplate, today, toTitleCase } from './Templates.js';
import { DEFAULT_SCENE_ID, SceneManager } from './SceneManager.js';
import { appendHookWarnings, getHookManager } from './HookManager.js';
import { EARS_ACCEPTANCE_EXAMPLE } from '../mcp/guidance.js';
import { VALID_SPEC_TRANSITIONS, isValidSpecTransition } from '../types/spec.js';
import type {
  Spec,
  SpecFrontmatter,
  SpecStatus,
  SpecDocument,
  CreateSpecInput,
} from '../types/spec.js';
import type { AiFollowupResponse } from '../types/response.js';

const SPEC_DOCS: SpecDocument[] = ['requirements', 'design', 'tasks'];

interface ExistingSpecInfo {
  spec: string;
  number: number;
  version: number;
  name: string;
}

export class SpecManager {
  constructor(
    private readonly fs: FileStorage,
    private readonly sceneManager: SceneManager,
  ) {}

  /**
   * 列出某 Scene 下所有 Spec。
   *
   * @param sceneInput 任意 Scene 标识（id/数字/名字），由 SceneManager.resolveId 归一化
   */
  async list(sceneInput: string): Promise<Spec[]> {
    const sceneId = await this.sceneManager.resolveId(sceneInput);
    const pattern = `.lrnev/scenes/${sceneId}/specs/*`;
    const files = await this.fs.list(pattern);
    files.sort();

    const specs: Spec[] = [];
    for (const file of files) {
      const specId = extractSpecIdFromPath(file);
      if (!specId) continue;
      try {
        specs.push(await this.get(sceneId, specId));
      } catch (err) {
        specs.push(makeBrokenSpec(this.fs, sceneId, specId, `${file}/requirements.md`, err));
      }
    }
    return specs;
  }

  /**
   * 读单个 Spec 详情。
   *
   * @param sceneInput Scene 标识
   * @param specInput  Spec 标识（完整 id 或 "01-00" 这种前缀）
   */
  async get(sceneInput: string, specInput: string): Promise<Spec> {
    const sceneId = await this.sceneManager.resolveId(sceneInput);
    const directDir = `.lrnev/scenes/${sceneId}/specs/${specInput}`;
    const specId = isFullSpecId(specInput) && this.fs.exists(directDir)
      ? specInput
      : await this.resolveId(sceneId, specInput);
    const dir = `.lrnev/scenes/${sceneId}/specs/${specId}`;
    const reqPath = `${dir}/requirements.md`;

    if (!this.fs.exists(reqPath)) {
      if (this.fs.exists(dir)) {
        throw new LrnevError(
          ErrorCode.SPEC_CORRUPTED,
          `Spec "${specInput}" 的 requirements.md 缺失`,
          { field: 'spec_id', hint: '运行 lrnev_doctor 定位损坏文件；若无法恢复，请用 spec_create 重新创建 Spec 骨架。' },
        );
      }
      throw new LrnevError(
        ErrorCode.SPEC_NOT_FOUND,
        `Spec "${specInput}" 不存在`,
        { field: 'spec_id', hint: '先调用 spec_list 查看当前 Scene 的完整 Spec id；若确实没有，请调用 spec_create 创建。' },
      );
    }

    const content = await this.fs.read(reqPath);
    const parsed = parseFrontmatter<SpecFrontmatter>(content);

    const { number, version, name } = parseSpecParts(specId);
    const documents = {
      requirements: this.fs.exists(`${dir}/requirements.md`),
      design: this.fs.exists(`${dir}/design.md`),
      tasks: this.fs.exists(`${dir}/tasks.md`),
    };

    return {
      ...parsed.frontmatter,
      spec: parsed.frontmatter.spec ?? specId,
      scene: parsed.frontmatter.scene ?? sceneId,
      status: parsed.frontmatter.status ?? 'draft',
      created: parsed.frontmatter.created ?? today(),
      path: this.fs.abs(dir),
      number,
      version,
      name,
      documents,
    };
  }

  /**
   * 按状态机更新 Spec 状态（draft→ready→in-progress→completed→archived）。
   *
   * 激活 types/spec.ts 的 VALID_SPEC_TRANSITIONS：合法转换写回 requirements.md
   * frontmatter（status + updated），非法转换抛 INVALID_STATUS_TRANSITION。
   * 相同状态幂等返回，不报错。lrnev 不替 AI 决定何时改状态，只提供这条改的通道。
   */
  async updateStatus(
    sceneInput: string,
    specInput: string,
    status: SpecStatus,
    reason?: string,
  ): Promise<AiFollowupResponse<Spec>> {
    const current = await this.get(sceneInput, specInput);
    const from = current.status;

    if (from !== status) {
      if (!isValidSpecTransition(from, status)) {
        const allowed = VALID_SPEC_TRANSITIONS[from];
        throw new LrnevError(
          ErrorCode.INVALID_STATUS_TRANSITION,
          `非法 Spec 状态转换：${from} → ${status}`,
          {
            field: 'status',
            hint: allowed.length > 0
              ? `当前 ${from} 只允许转换到：${allowed.join('、')}`
              : `${from} 是终态，不能再转换；如需重做请用 spec_create 开新版`,
          },
        );
      }
      const reqPath = `.lrnev/scenes/${current.scene}/specs/${current.spec}/requirements.md`;
      const content = await this.fs.read(reqPath);
      const parsed = parseFrontmatter<SpecFrontmatter>(content);
      const next = { ...parsed.frontmatter, status, updated: today() };
      await this.fs.write(reqPath, serializeFrontmatter(next, parsed.body));
    }

    const data = await this.get(current.scene, current.spec);
    const instructions = from === status
      ? [`Spec "${data.spec}" 已是 ${status}，无需变更。`]
      : [`Spec "${data.spec}" 状态 ${from} → ${status}${reason ? `（${reason}）` : ''}。`];
    if (status === 'archived') {
      instructions.push('已归档：该 Spec 的待办任务不再出现在 project_status 的可领任务列表。');
    }
    return { ok: true, data, ai_followup: { instructions } };
  }

  /**
   * 创建 Spec。
   *
   * 流程：
   *   1. 校验 Scene 存在
   *   2. 校验 name 是 kebab-case
   *   3. 分配 Scene 内序号（不重用）
   *   4. 校验 id 不冲突
   *   5. 渲染三文档模板
   *   6. 返回 ai_followup
   */
  async create(input: CreateSpecInput): Promise<AiFollowupResponse<Spec>> {
    const sceneId = input.scene === undefined
      ? (await this.sceneManager.ensureExists(DEFAULT_SCENE_ID)).id
      : await this.sceneManager.resolveId(input.scene);
    validateSpecName(input.name);

    const version = input.version ?? 0;
    if (!Number.isInteger(version) || version < 0 || version > 99) {
      throw new LrnevError(
        ErrorCode.INVALID_INPUT,
        `Spec 版本号必须是 0~99 整数：${version}`,
        { field: 'version' },
      );
    }

    const { spec, siblingSpecIds } = await this.fs.withDirectoryLock(
      `.lrnev/locks/create-spec-${safeId(sceneId)}.lockdir`,
      () => this.createUnderLock(sceneId, input, version),
    );

    const hookResult = await getHookManager(this.fs.root).trigger('spec.create', {
      scene: sceneId,
      spec: spec.spec,
      name: spec.name,
      path: spec.path,
      priority: input.priority,
    });

    const instructions = [
      `【事实】Spec "${spec.spec}" 已创建于 Scene "${sceneId}"，路径 .lrnev/scenes/${sceneId}/specs/${spec.spec}`,
      `【建议】如果这是已有特性的增量，通常可以考虑 context_search 找到对应 Spec 用 task_create 落位。判断时注意：整体推翻已有 requirements/design → 通常建议开新版（version+1）保留旧版对照；独立且可验收的新特性 → 通常建议开新 Spec；旧 Spec 出现上下文冷却信号（长时间未动、已 completed、tasks 已清空）→ 先读摘要再决定复用、开新版还是独立 Spec。scene 选择时，优先归入已有匹配业务域 scene；只有用户明确确认、或上下文非常清楚这是会承载多个 spec 的新业务域，才 scene_create；零散无稳定业务域的小型独立特性才落 00-default（兜底）。`,
      `【重要】以上是治理建议，不代表本次创建失败。若用户已明确要求创建独立 Spec，不得擅自撤销或回退。建议下一步：调用 context_search 查找相关需求，或问用户该 Spec 的具体范围。`,
      '请协助用户填充 requirements.md 的"目标"、"用户故事"、"详细需求"',
      '注意：三文档的章节标题是模板契约，不要翻译或改名（ready gate 按中文标题精确匹配，如「L0 摘要」「详细需求」），只填标题下的内容。',
      '需求填完后调用 spec_gate_check(gate=ready) 检查',
      '通过后再填 design.md（技术方案），最后填 tasks.md（任务清单）',
      '关键决策出现时主动询问用户是否生成 ADR（参考 context://steering/adr）',
      EARS_ACCEPTANCE_EXAMPLE,
    ];
    if (siblingSpecIds.length > 0) {
      instructions.push(
        `本 Scene 已有 Spec：${siblingSpecIds.join('、')}。你的改动可能与它们相关，建议先读它们按文档键控的 L0 摘要或用 context_search 确认有无冲突/复用。`,
      );
    }

    const suggestedTools: Array<{ name: string; args_template: Record<string, unknown>; reason: string }> = [
      {
        name: 'spec_gate_check',
        args_template: { scene: sceneId, spec: spec.spec, gate: 'ready' },
        reason: '需求填完后检查是否可进入实施',
      },
      {
        name: 'summarize_save',
        args_template: {
          uri: `context://spec/${sceneId}/${spec.spec}`,
          l0: '<一句话摘要>',
          l1: '<约 2000 token 概览>',
        },
        reason: '需求稳定后生成 L0/L1，便于跨 Spec 检索',
      },
    ];

    // 重写版引导归档旧版：version>0 且存在同名、更低版本的旧 Spec 时，
    // surface 归档动作（不自动归档，是否归档由 AI/用户判断）。
    if (version > 0) {
      const prevId = siblingSpecIds
        .map((id) => ({ id, parts: tryParseSpecParts(id) }))
        .filter((s) => s.parts && s.parts.name === input.name && s.parts.version < version)
        .sort((a, b) => b.parts!.version - a.parts!.version)[0]?.id;
      if (prevId) {
        instructions.push(
          `检测到这是 ${prevId} 的重写版。若旧版方案已被本版取代，可用 spec_update 把 ${prevId} 标记为 archived（归档后它的待办任务不再出现在 project_status 的可领列表）；是否归档由你和用户判断，lrnev 不自动归档。`,
        );
        suggestedTools.push({
          name: 'spec_update',
          args_template: { scene: sceneId, spec: prevId, status: 'archived' },
          reason: '旧版方案已被本重写版取代时归档旧版',
        });
      }
    }

    return appendHookWarnings({
      ok: true,
      data: spec,
      ai_followup: {
        instructions,
        suggested_tools: suggestedTools,
      },
    }, hookResult.warnings);
  }

  /**
   * 解析 Spec 标识。
   *
   * 支持：
   *   1. 完整 id："01-00-user-login"
   *   2. 序号-版本前缀："01-00" / "01"（仅当 Scene 内唯一时）
   *   3. 纯名字："user-login"（仅当 Scene 内唯一时）
   */
  async resolveId(sceneInput: string, input: string): Promise<string> {
    const sceneId = await this.sceneManager.resolveId(sceneInput);

    if (!input) {
      throw new LrnevError(ErrorCode.INVALID_INPUT, 'Spec 标识不能为空', {
        field: 'spec_id',
      });
    }

    const pattern = `.lrnev/scenes/${sceneId}/specs/*/requirements.md`;
    const files = await this.fs.list(pattern);
    const allIds = files.map(extractSpecIdFromPath).filter((x): x is string => !!x).sort();

    // 完整 id 命中
    if (allIds.includes(input)) return input;

    // 序号-版本前缀（如 01-00）
    if (/^\d+(-\d+)?$/.test(input)) {
      const candidates = allIds.filter((id) => id.startsWith(input + '-'));
      if (candidates.length === 1) return candidates[0]!;
      if (candidates.length > 1) {
        throw new LrnevError(
          ErrorCode.AMBIGUOUS_REF,
          `Spec 前缀 "${input}" 不唯一：${candidates.join(', ')}`,
          {
            field: 'spec_id',
            hint: '请从 candidates 选择一个完整 Spec id，并用该完整 id 重新调用当前工具。',
            candidates,
          },
        );
      }
    }

    // 纯名字（最后一段）
    const byName = allIds.filter((id) => tryParseSpecParts(id)?.name === input);
    if (byName.length === 1) return byName[0]!;
    if (byName.length > 1) {
      throw new LrnevError(
        ErrorCode.AMBIGUOUS_REF,
        `Spec 名 "${input}" 不唯一：${byName.join(', ')}`,
        {
          field: 'spec_id',
          hint: '请从 candidates 选择一个完整 Spec id，并用该完整 id 重新调用当前工具。',
          candidates: byName,
        },
      );
    }

    throw new LrnevError(
      ErrorCode.SPEC_NOT_FOUND,
      `Scene "${sceneId}" 内找不到 Spec "${input}"`,
      { field: 'spec_id', hint: '先调用 spec_list 查看现有 Spec；若这是新特性，请调用 spec_create 创建。' },
    );
  }

  /**
   * 决定新 Spec 的主序号。
   *
   * 首版（version=0）或全新名字：使用 Scene 内下一个递增序号。
   * 重写版（同名 version>0）：沿用该名字已有 Spec 的主序号，只递增版本位，
   * 这样 `01-00-foo` 的重写版会是 `01-01-foo`，符合 design.md 的版本语义。
   */
  private resolveNumberForCreate(existing: ExistingSpecInfo[], name: string, version: number): number {
    const sameNameSpecs = existing.filter((s) => s.name === name);
    if (sameNameSpecs.length > 0) {
      if (version === 0) {
        return this.nextNumberFromExisting(existing);
      }
      return Math.min(...sameNameSpecs.map((s) => s.number));
    }
    return this.nextNumberFromExisting(existing);
  }

  private nextNumberFromExisting(existing: ExistingSpecInfo[]): number {
    let max = 0;
    for (const spec of existing) {
      if (spec.number > max) max = spec.number;
    }
    return max + 1;
  }

  private async createUnderLock(
    sceneId: string,
    input: CreateSpecInput,
    version: number,
  ): Promise<{ spec: Spec; siblingSpecIds: string[] }> {
    const existing = await this.listExistingSpecInfo(sceneId);
    const siblingSpecIds = existing.map((s) => s.spec);
    const sameName = existing.find((s) => s.name === input.name && s.version === version);
    if (sameName) {
      throw new LrnevError(
        ErrorCode.INVALID_INPUT,
        `Scene "${sceneId}" 内已有同名 Spec："${sameName.spec}"`,
        { field: 'name', hint: '若是重写，请指定 version > 0' },
      );
    }

    let number = this.resolveNumberForCreate(existing, input.name, version);
    const maxAttempts = loadConfig(this.fs.root).spec.create_max_attempts;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      const specId = formatSpecId(number, version, input.name);
      const dir = `.lrnev/scenes/${sceneId}/specs/${specId}`;
      const date = today();
      const titleName = `${String(number).padStart(2, '0')}-${String(version).padStart(2, '0')} ${toTitleCase(input.name)}`;
      const vars = {
        spec_id: specId,
        scene_id: sceneId,
        name_title: titleName,
        date,
        priority_line: input.priority ? `priority: ${input.priority}\n` : '',
      };

      const requirements = await renderTemplate('spec', 'requirements.md', vars);
      const design = await renderTemplate('spec', 'design.md', vars);
      const tasksTmpl = await renderTemplate('spec', 'tasks.md', vars);

      if (!await this.fs.mkdirExclusive(dir)) {
        number++;
        continue;
      }

      await this.fs.write(`${dir}/requirements.md`, requirements);
      await this.fs.write(`${dir}/design.md`, design);
      await this.fs.write(`${dir}/tasks.md`, tasksTmpl);

      return {
        spec: await this.get(sceneId, specId),
        siblingSpecIds,
      };
    }

    throw new LrnevError(
      ErrorCode.INVALID_INPUT,
      `Spec 序号分配重试耗尽：${input.name}`,
      { field: 'number', hint: '检查该 Scene 下 specs 目录是否有并发创建或损坏目录' },
    );
  }

  /** 列出 Scene 下已有 Spec 的 id/序号/版本信息，供分配序号与轻量依赖提示复用。 */
  private async listExistingSpecInfo(sceneId: string): Promise<ExistingSpecInfo[]> {
    const dirs = await this.fs.list(`.lrnev/scenes/${sceneId}/specs/*`);
    const specs = dirs
      .map(extractSpecIdFromPath)
      .filter((id): id is string => !!id)
      .sort();
    const existing: ExistingSpecInfo[] = [];
    for (const spec of specs) {
      const parts = tryParseSpecParts(spec);
      if (parts) existing.push({ spec, ...parts });
    }
    return existing;
  }
}

/** 校验 Spec name */
function validateSpecName(name: string): void {
  if (!name) {
    throw new LrnevError(ErrorCode.INVALID_INPUT, 'Spec name 不能为空', { field: 'name' });
  }
  if (name.length < 2 || name.length > 64) {
    throw new LrnevError(ErrorCode.INVALID_INPUT, `Spec name 长度需在 2~64："${name}"`, {
      field: 'name',
    });
  }
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(name)) {
    throw new LrnevError(
      ErrorCode.INVALID_INPUT,
      `Spec name 必须是 kebab-case："${name}"`,
      { field: 'name', hint: '例：user-login、password-reset' },
    );
  }
}

/** {NN:02d}-{VV:02d}-{name} */
export function formatSpecId(number: number, version: number, name: string): string {
  assertTwoDigitNumber(number, 'number', 'Spec 序号', 1);
  assertTwoDigitNumber(version, 'version', 'Spec 版本号', 0);
  return `${String(number).padStart(2, '0')}-${String(version).padStart(2, '0')}-${name}`;
}

/** 拆分 "01-00-user-login" → { number: 1, version: 0, name: 'user-login' } */
export function parseSpecParts(specId: string): {
  number: number;
  version: number;
  name: string;
} {
  const m = /^(\d{2})-(\d{2})-([a-z0-9]+(?:-[a-z0-9]+)*)$/.exec(specId);
  if (!m) {
    throw new LrnevError(
      ErrorCode.INVALID_INPUT,
      `Spec id 格式无效："${specId}"，应为 {NN}-{VV}-{kebab-name}`,
      { field: 'spec_id' },
    );
  }
  const number = parseInt(m[1]!, 10);
  const version = parseInt(m[2]!, 10);
  if (number < 1) {
    throw new LrnevError(
      ErrorCode.INVALID_INPUT,
      `Spec 序号必须是 1~99 整数："${specId}"`,
      { field: 'spec_id' },
    );
  }
  return {
    number,
    version,
    name: m[3]!,
  };
}

export function tryParseSpecParts(specId: string): {
  number: number;
  version: number;
  name: string;
} | null {
  try {
    return parseSpecParts(specId);
  } catch {
    return null;
  }
}

function assertTwoDigitNumber(
  value: number,
  field: string,
  label: string,
  min: number,
): void {
  if (!Number.isInteger(value) || value < min || value > 99) {
    throw new LrnevError(
      ErrorCode.INVALID_INPUT,
      `${label}必须是 ${min}~99 整数：${value}`,
      { field },
    );
  }
}

/** 从 "scenes/{scene}/specs/{spec}/requirements.md" 抽 specId */
function extractSpecIdFromPath(path: string): string | null {
  const m = /^\.lrnev\/scenes\/[^/]+\/specs\/([^/]+)(?:\/requirements\.md)?$/.exec(path);
  return m ? m[1]! : null;
}

function isFullSpecId(input: string): boolean {
  return /^\d+-\d+-/.test(input);
}

function makeBrokenSpec(
  fs: FileStorage,
  sceneId: string,
  specId: string,
  requirementsPath: string,
  err: unknown,
): Spec {
  const { number, version, name } = tryParseSpecParts(specId) ?? {
    number: -1,
    version: -1,
    name: specId,
  };
  const dir = `.lrnev/scenes/${sceneId}/specs/${specId}`;
  return {
    spec: specId,
    scene: sceneId,
    status: 'draft',
    created: today(),
    path: fs.abs(dir),
    number,
    version,
    name,
    documents: {
      requirements: fs.exists(`${dir}/requirements.md`),
      design: fs.exists(`${dir}/design.md`),
      tasks: fs.exists(`${dir}/tasks.md`),
    },
    broken: {
      error: err instanceof Error ? err.message : String(err),
      path: fs.abs(requirementsPath),
    },
  };
}

function safeId(value: string): string {
  return value.replace(/[^a-zA-Z0-9._-]+/g, '_');
}

export { SPEC_DOCS, validateSpecName };

